#!/usr/bin/env python3
"""Enumerate all terminal observable outcomes of a mixed-width buffered machine.

Model (deliberately specified TSO-like teaching model):

State per thread: program counter, FIFO store buffer, observation list.
Shared memory: list of byte values.

Transitions:
  * execute next instruction of any thread (program order):
      - store: append (address,width,value) to that thread's FIFO buffer
      - load:  per byte, youngest covering buffered store of the *same* thread
               wins, else shared memory; assembled little-endian -> observation
      - fence: enabled only when the thread's buffer is empty
      - xchg:  enabled only when the thread's buffer is empty; atomically read
               the shared-memory value into observations and write the new value
  * drain: oldest store of any non-empty buffer becomes globally visible
           (all of its bytes at once).

Terminal: every thread finished and every buffer empty.

Because observations already recorded are a pure prefix and the future depends
only on (program counters, buffers, shared memory), the search memoizes on that
"core" state and returns the set of (future observations per thread, final
memory) pairs reachable from it.
"""

import json
import sys


def solve(request):
    memory0 = tuple(int(b) & 0xFF for b in request["memory"])
    threads = tuple(tuple(tuple(op) for op in prog) for prog in request["threads"])
    nthreads = len(threads)
    lens = tuple(len(p) for p in threads)

    # ---------- helpers ----------
    def read_shared(memory, addr, width):
        v = 0
        for i in range(width):
            v |= memory[addr + i] << (8 * i)
        return v

    def read_forwarded(buffer, memory, addr, width):
        """Byte-wise read: youngest covering buffered store wins, else memory."""
        v = 0
        for i in range(width):
            a = addr + i
            byte = None
            for s_addr, s_width, s_val in reversed(buffer):
                if s_addr <= a < s_addr + s_width:
                    byte = (s_val >> (8 * (a - s_addr))) & 0xFF
                    break
            if byte is None:
                byte = memory[a]
            v |= byte << (8 * i)
        return v

    def write_shared(memory, addr, width, value):
        m = list(memory)
        for i in range(width):
            m[addr + i] = (value >> (8 * i)) & 0xFF
        return tuple(m)

    empty_reads = tuple(tuple() for _ in range(nthreads))
    memo = {}

    def bump(pcs, t, value):
        return pcs[:t] + (value,) + pcs[t + 1:]

    def setbuf(buffers, t, buf):
        return buffers[:t] + (buf,) + buffers[t + 1:]

    def compute(pcs, buffers, memory):
        """Return set of (reads_tuple, final_memory) reachable from this core state.

        reads_tuple is the tuple (per thread) of observations still to be
        produced *after* reaching this state.
        """
        key = (pcs, buffers, memory)
        cached = memo.get(key)
        if cached is not None:
            return cached

        results = set()

        # 1. execute the next instruction of some thread
        for t in range(nthreads):
            pc = pcs[t]
            if pc >= lens[t]:
                continue
            op = threads[t][pc]
            kind = op[0]
            buf = buffers[t]
            if kind == "store":
                newbuf = buf + ((op[1], op[2], op[3]),)
                sub = compute(bump(pcs, t, pc + 1), setbuf(buffers, t, newbuf), memory)
                results.update(sub)
            elif kind == "load":
                value = read_forwarded(buf, memory, op[1], op[2])
                sub = compute(bump(pcs, t, pc + 1), buffers, memory)
                for reads, mem in sub:
                    results.add(
                        (reads[:t] + ((value,) + reads[t],) + reads[t + 1:], mem)
                    )
            elif kind == "fence":
                if not buf:
                    results.update(compute(bump(pcs, t, pc + 1), buffers, memory))
            elif kind == "xchg":
                if not buf:
                    value = read_shared(memory, op[1], op[2])
                    newmem = write_shared(memory, op[1], op[2], op[3])
                    sub = compute(bump(pcs, t, pc + 1), buffers, newmem)
                    for reads, mem in sub:
                        results.add(
                            (reads[:t] + ((value,) + reads[t],) + reads[t + 1:], mem)
                        )
            else:
                # unknown instruction: not expected for valid input; skip safely
                results.update(compute(bump(pcs, t, pc + 1), buffers, memory))

        # 2. drain the oldest store of some non-empty buffer
        for t in range(nthreads):
            buf = buffers[t]
            if buf:
                s_addr, s_width, s_val = buf[0]
                newmem = write_shared(memory, s_addr, s_width, s_val)
                results.update(
                    compute(pcs, setbuf(buffers, t, buf[1:]), newmem)
                )

        # terminal state: no thread can step and no buffer holds a store
        if not any(buffers) and all(pcs[t] >= lens[t] for t in range(nthreads)):
            results.add((empty_reads, memory))

        memo[key] = results
        return results

    initial = compute(
        tuple(0 for _ in range(nthreads)),
        tuple(tuple() for _ in range(nthreads)),
        memory0,
    )

    outcomes = []
    for reads, mem in initial:
        outcomes.append(
            {
                "reads": [list(r) for r in reads],
                "memory": list(mem),
            }
        )
    return {"outcomes": outcomes}


def main():
    sys.setrecursionlimit(100000)
    out = sys.stdout
    for line in sys.stdin:
        if not line.strip():
            continue
        request = json.loads(line)
        response = solve(request)
        out.write(json.dumps(response) + "\n")
    out.flush()


if __name__ == "__main__":
    main()
