"""Independent brute-force: plain DFS over full states (no memoization)."""
import json, sys
sys.setrecursionlimit(100000)

def solve(request):
    mem0 = list(request['memory'])
    threads = request['threads']
    T = len(threads)
    out = set()
    seen = set()

    def rf(buf, mem, addr, width):
        v = 0
        for i in range(width):
            a = addr + i
            b = None
            for sa, sw, sv in reversed(buf):
                if sa <= a < sa + sw:
                    b = (sv >> (8*(a-sa))) & 0xFF
                    break
            if b is None:
                b = mem[a]
            v |= b << (8*i)
        return v

    def dfs(pcs, bufs, mem, obs):
        state = (tuple(pcs), tuple(tuple(b) for b in bufs), tuple(mem), tuple(tuple(o) for o in obs))
        # no memo on obs; dedupe only to bound work of pure-exploration duplicates?
        # do NOT dedupe (would be same logic as main). Explore all paths.
        any_enabled = False
        for t in range(T):
            pc = pcs[t]
            if pc < len(threads[t]):
                op = threads[t][pc]
                k = op[0]
                buf = bufs[t]
                if k == 'store':
                    nb = list(buf); nb.append((op[1], op[2], op[3]))
                    npcs = list(pcs); npcs[t] += 1
                    nbufs = [list(b) for b in bufs]; nbufs[t] = nb
                    any_enabled = True
                    dfs(npcs, nbufs, list(mem), [list(o) for o in obs])
                elif k == 'load':
                    v = rf(buf, mem, op[1], op[2])
                    npcs = list(pcs); npcs[t] += 1
                    nobs = [list(o) for o in obs]; nobs[t].append(v)
                    any_enabled = True
                    dfs(npcs, [list(b) for b in bufs], list(mem), nobs)
                elif k == 'fence':
                    if not buf:
                        npcs = list(pcs); npcs[t] += 1
                        any_enabled = True
                        dfs(npcs, [list(b) for b in bufs], list(mem), [list(o) for o in obs])
                elif k == 'xchg':
                    if not buf:
                        addr, w, val = op[1], op[2], op[3]
                        v = 0
                        for i in range(w):
                            v |= mem[addr+i] << (8*i)
                        nmem = list(mem)
                        for i in range(w):
                            nmem[addr+i] = (val >> (8*i)) & 0xFF
                        npcs = list(pcs); npcs[t] += 1
                        nobs = [list(o) for o in obs]; nobs[t].append(v)
                        any_enabled = True
                        dfs(npcs, [list(b) for b in bufs], nmem, nobs)
        for t in range(T):
            if bufs[t]:
                sa, sw, sv = bufs[t][0]
                nmem = list(mem)
                for i in range(sw):
                    nmem[sa+i] = (sv >> (8*i)) & 0xFF
                nbufs = [list(b) for b in bufs]; nbufs[t] = bufs[t][1:]
                any_enabled = True
                dfs(list(pcs), nbufs, nmem, [list(o) for o in obs])
        if not any_enabled:
            assert all(pcs[t] >= len(threads[t]) for t in range(T)) and not any(bufs)
            out.add((tuple(tuple(o) for o in obs), tuple(mem)))

    dfs([0]*T, [[] for _ in range(T)], list(mem0), [[] for _ in range(T)])
    return {"outcomes": [{"reads": [list(r) for r in reads], "memory": list(m)} for reads, m in out]}

if __name__ == '__main__':
    for line in sys.stdin:
        if not line.strip(): continue
        print(json.dumps(solve(json.loads(line))))
